os.makedirs('/kaggle/working/parts', exist_ok=True)
audio_files = []

for i, text in enumerate(sections, 1):
    print(f'\n🎙️ Generating Section {i}/{len(sections)} in Teacher Voice (mesir)...')
    t0 = time.time()
    payload = {
        'model': 'tts-1',
        'voice': 'mesir',
        'input': text,
        'response_format': 'wav'
    }
    r = requests.post('http://127.0.0.1:3900/v1/audio/speech', json=payload, timeout=300)
    elapsed = time.time() - t0
    
    if r.status_code == 200:
        filename = f'/kaggle/working/parts/part_{i:02d}.wav'
        with open(filename, 'wb') as f:
            f.write(r.content)
        audio_files.append(filename)
        print(f'✅ Section {i} generated in {elapsed:.1f}s ({len(r.content):,} bytes)')
    else:
        print(f'❌ Error on Section {i}: HTTP {r.status_code} - {r.text}')

print('\n🔗 Merging all sections into Chapter_01_Teacher_Marathon.wav...')
with open('/kaggle/working/concat.txt', 'w') as f:
    for a in audio_files:
        f.write(f'file \'{a}\'\n')

final_out = '/kaggle/working/Chapter_01_Teacher_Marathon.wav'
os.system(f'ffmpeg -y -f concat -safe 0 -i /kaggle/working/concat.txt -c copy {final_out}')
print('\n' + '='*60)
print('🎉 MASTER LECTURE GENERATION COMPLETE!')
print(f'📁 Audio File: {final_out}')
print('='*60)
